use shmem_ipc::{sharedring, ShmemConf};
use std::error::Error;
use std::time::Duration;

const RING_SIZE: usize = 1024;

fn main() -> Result<(), Box<dyn Error>> {
    // Create a shared memory ring buffer
    let (mut producer, mut consumer) = ShmemConf::new()
        .size(RING_SIZE)
        .create_ringbuffer::<u8>()
        .expect("Failed to create shared ring buffer");

    // Simulate writing a serialized PluginObjectBlob to the shared ring buffer
    let blob_data = b"This is a simulated PluginObjectBlob for shmem-ipc.";
    producer.write_all(blob_data)?;
    println!("Producer wrote: {:?}", blob_data);

    // Simulate another process (consumer) reading the blob
    let mut read_buffer = vec![0; blob_data.len()];
    consumer.read_exact(&mut read_buffer)?;
    println!("Consumer read: {:?}", &read_buffer);

    Ok(())
}
