use serde::{Deserialize, Serialize};
use serde_evolve::Versioned;

// Define version 1 of the plugin configuration
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct PluginConfigV1 {
    pub name: String,
    pub version: u32,
    pub enabled: bool,
}

// Define version 2 of the plugin configuration
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct PluginConfigV2 {
    pub plugin_name: String, // Renamed field
    pub schema_version: u32, // Renamed field
    pub is_active: bool,     // Renamed field
    pub description: Option<String>, // New field
}

// Define the migration from V1 to V2
impl From<PluginConfigV1> for PluginConfigV2 {
    fn from(v1: PluginConfigV1) -> Self {
        Self {
            plugin_name: v1.name,
            schema_version: v1.version,
            is_active: v1.enabled,
            description: None, // Default value for new field
        }
    }
}

// Define the final domain type, which can be migrated to from any previous version
#[derive(Clone, Debug, Versioned, PartialEq, Eq)]
#[versioned(
    mode = "infallible",
    chain(PluginConfigV1, PluginConfigV2),
)]
pub struct CurrentPluginConfig {
    pub plugin_name: String,
    pub schema_version: u32,
    pub is_active: bool,
    pub description: Option<String>,
}

// Migration from V2 to CurrentPluginConfig (if CurrentPluginConfig is identical to V2, this is trivial)
impl From<PluginConfigV2> for CurrentPluginConfig {
    fn from(v2: PluginConfigV2) -> Self {
        Self {
            plugin_name: v2.plugin_name,
            schema_version: v2.schema_version,
            is_active: v2.is_active,
            description: v2.description,
        }
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Simulate loading an old V1 blob
    let old_v1_json = r#"{"_version":1,"name":"MyOldPlugin","version":1,"enabled":true}"#;
    let versioned_config: CurrentPluginConfig = serde_json::from_str(old_v1_json)?;

    println!("Migrated V1 config: {:?}", versioned_config);
    assert_eq!(versioned_config.plugin_name, "MyOldPlugin");
    assert_eq!(versioned_config.schema_version, 1);
    assert_eq!(versioned_config.is_active, true);
    assert_eq!(versioned_config.description, None);

    // Simulate loading a V2 blob
    let v2_json = r#"{"_version":2,"plugin_name":"MyNewPlugin","schema_version":2,"is_active":false,"description":"A new plugin"}"#;
    let versioned_config_v2: CurrentPluginConfig = serde_json::from_str(v2_json)?;

    println!("Migrated V2 config: {:?}", versioned_config_v2);
    assert_eq!(versioned_config_v2.plugin_name, "MyNewPlugin");
    assert_eq!(versioned_config_v2.schema_version, 2);
    assert_eq!(versioned_config_v2.is_active, false);
    assert_eq!(versioned_config_v2.description, Some("A new plugin".to_string()));

    Ok(())
}
```

### Gotchas & Constraints
*   **Hash Collisions**: While highly improbable with strong cryptographic hashes like BLAKE3 or SHA256, the theoretical possibility of a hash collision exists. This could lead to two different schemas being identified by the same hash, potentially causing data corruption or unexpected behavior. Mitigation often involves using sufficiently long hash outputs and potentially adding secondary verification.
*   **Migration Complexity**: As schemas evolve, the migration logic can become increasingly complex, especially with many versions and significant structural changes. Manual implementation of `From`/`TryFrom` traits for each version transition can be tedious and error-prone. Thorough testing of all migration paths is crucial.
*   **Performance Overhead**: Generating JSON schemas, calculating hashes, and performing migrations (especially complex ones) introduce computational overhead. For high-throughput systems, the performance impact of these operations needs to be carefully measured and optimized. Caching of schemas and pre-computed hashes can help.
*   **Backward/Forward Compatibility**: While `serde-evolve` aids in managing compatibility, it's still up to the developer to design schemas and migrations that are truly backward and, if necessary, forward compatible. Adding non-optional fields without default values in newer versions, for instance, will break deserialization of older data unless handled explicitly in migrations.
*   **Schema Definition Language**: Relying solely on `schemars`-derived JSON Schema might not capture all nuances of a Rust type system (e.g., certain Rust-specific constraints or custom types). This might require augmenting the JSON Schema with custom extensions or additional metadata to fully describe the `PluginObjectBlob`'s data contract.
*   **Storage Management**: For append-only logs, the storage requirements can grow indefinitely. A strategy for archiving or pruning old, unused `PluginObjectBlob` versions and their associated schemas will be necessary to manage storage costs and performance.

