use extism::{Plugin, Manifest, Wasm};
use serde_json::json;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let manifest = Manifest::new([
        Wasm::file("path/to/your/plugin.wasm"), // Replace with actual path to your compiled WASM plugin
    ]);

    let mut plugin = Plugin::new(manifest, [], true)?;

    let input_data = json!({
        "data": "Hello from host!",
        "config": {"log_level": "info"}
    });

    let output = plugin.call("handle_data", input_data.to_string().as_bytes())?;

    let output_str = String::from_utf8(output)?;
    println!("Plugin output: {}", output_str);

    Ok(())
}
