use extism_pdk::{
    plugin_fn, FnResult, Json, 
    // Assuming PluginInput and PluginOutput are defined in a shared crate or copied
    // For a real scenario, these would likely be in a shared `wit` or `interface` crate
};
use serde::{Deserialize, Serialize};

#[derive(Debug, Serialize, Deserialize)]
pub struct PluginInput {
    pub data: String,
    pub config: serde_json::Value,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct PluginOutput {
    pub result: String,
    pub status_code: u16,
}

#[plugin_fn]
pub fn handle_data(Json(input): Json<PluginInput>) -> FnResult<Json<PluginOutput>> {
    println!("Plugin received data: {}", input.data);
    println!("Plugin config: {:?}", input.config);

    let response = PluginOutput {
        result: format!("Processed: {}", input.data.to_uppercase()),
        status_code: 200,
    };

    Ok(Json(response))
}
